// testing/T393 (RED for testing/D1) and testing/T394 (control): classify(mapping, files) with inherited Object.prototype keys.
//
// This file is RED by design on ec31e685 and sits outside package.json scripts.test so npm test stays green.
// Run by hand:
//   node --test packages/kaal-testing/15-defects/classify-inherited-keys.red.mjs
//
// testing/D1 is answered when testing/T393 passes unmodified alongside testing/T394 in the separate fix Change for lib/contracts.mjs. Do not edit this file to pass.
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { sha256 } from 'kaal-testing/acceptance';
import { classify, problems } from 'kaal-testing/contracts';

const OWNER = { kind: 'capability', name: 'Sample', id: 'a'.repeat(64) };
const QUOTE = 'Sample refuses what is out of scope.';

async function makeMapping({ source = 'x/README.md', evidenceFile = null } = {}) {
  const qHash = await sha256(Buffer.from(QUOTE));
  const evHash = await sha256(Buffer.from('it("x", () => {});\n'));
  const evidence = evidenceFile ? [{ file: evidenceFile, sha256: evHash, test: ['Sample', 'x'] }] : [];
  return {
    owner: OWNER,
    statements: [
      {
        source,
        quote: QUOTE,
        sha256: qHash,
        loop: 'acceptance',
        evidence,
        ...(evidence.length ? { inference: 'infers claim', limits: 'one witness' } : {}),
        review: null,
      },
    ],
  };
}

describe('testing/D1 parked Cases: inherited Object.prototype file keys in classify()', () => {
  it('testing/T394 control: absent safe paths and null-prototype files map return unknown without throwing', async () => {
    const safe = await makeMapping({ source: 'x/README.md', evidenceFile: 'x/test/a.test.mjs' });
    assert.deepEqual(problems(safe, OWNER), []);
    const [rSafe] = await classify(safe, {});
    assert.equal(rSafe.class, 'unknown');
    assert.equal(rSafe.reason, 'the statement is no longer in x/README.md (stale)');

    const nullProtoFiles = Object.assign(Object.create(null), { 'x/README.md': Buffer.from(`${QUOTE}\n`) });
    const evInherited = await makeMapping({ source: 'x/README.md', evidenceFile: 'toString' });
    assert.deepEqual(problems(evInherited, OWNER), []);
    const [rEv] = await classify(evInherited, nullProtoFiles);
    assert.equal(rEv.class, 'unknown');
    assert.equal(rEv.evidence[0].class, 'unknown');
    assert.equal(rEv.evidence[0].reason, 'toString is missing');
  });

  it('testing/T393 RED (testing/D1): valid mappings naming inherited Object.prototype keys in s.source or e.file classify as unknown without throwing', async (t) => {
    for (const key of ['toString', '__proto__', 'constructor']) {
      await t.test(`s.source=${key}`, async () => {
        const mSource = await makeMapping({ source: key });
        assert.deepEqual(problems(mSource, OWNER), [], `expected problems() === [] for s.source=${key}`);
        const [outSource] = await classify(mSource, {});
        assert.equal(outSource.class, 'unknown');
        assert.equal(outSource.reason, `the statement is no longer in ${key} (stale)`);
      });

      await t.test(`e.file=${key}`, async () => {
        const mEvidence = await makeMapping({ source: 'x/README.md', evidenceFile: key });
        assert.deepEqual(problems(mEvidence, OWNER), [], `expected problems() === [] for e.file=${key}`);
        const [outEvidence] = await classify(mEvidence, { 'x/README.md': Buffer.from(`${QUOTE}\n`) });
        assert.equal(outEvidence.class, 'unknown');
        assert.equal(outEvidence.evidence[0].class, 'unknown');
        assert.equal(outEvidence.evidence[0].reason, `${key} is missing`);
      });
    }
  });
});
